import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});
import { query, update } from '../db.js';
import { UserRepository } from '../repositories/user-repository.js';

const users = new UserRepository();

// Callback-style database access. Chapter 5 migrates this to UserRepository.
// listActiveUsers already goes through the repository; it keeps the callback
// signature so existing callers (routes.js) don't change.
export function listActiveUsers(callback) {
  users.findActive().then((rows) => callback(null, rows), (err) => callback(err));
}

export function findUser(id, callback) {
  query('users', (u) => u.id === id, (err, rows) => {
    if (err) return callback(err);
    callback(null, rows[0] ?? null);
  });
}

export function softDeleteUser(id, when, callback) {
  update('users', id, { deleted_at: when }, callback);
}
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { listActiveUsers, findUser } from '../src/services/user-service.js';
import { UserRepository } from '../src/repositories/user-repository.js';

test('listActiveUsers excludes soft-deleted users', (t, done) => {
  listActiveUsers((err, users) => {
    assert.equal(err, null);
    assert.equal(users.length, 2);
    assert.ok(users.every((u) => u.deleted_at === null));
    done();
  });
});

test('listActiveUsers reads through UserRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findActive = t.mock.method(UserRepository.prototype, 'findActive', () => Promise.reject(boom));
  listActiveUsers((err, users) => {
    assert.equal(findActive.mock.callCount(), 1);
    assert.equal(err, boom);
    assert.equal(users, undefined);
    done();
  });
});

test('findUser returns null for an unknown id', (t, done) => {
  findUser(999, (err, user) => {
    assert.equal(err, null);
    assert.equal(user, null);
    done();
  });
});
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { UserRepository } from '../src/repositories/user-repository.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('UserRepository.findActive matches the service behaviour', async () => {
  const users = await new UserRepository().findActive();
  assert.equal(users.length, 2);
});

test('UserRepository.findByEmail returns the active user or null', async () => {
  const repo = new UserRepository();
  const ada = await repo.findByEmail('ada@example.com');
  assert.equal(ada.id, 1);
  assert.equal(await repo.findByEmail('alan@example.com'), null); // soft-deleted
  assert.equal(await repo.findByEmail('nobody@example.com'), null);
});

test('OrderRepository.findPaid matches the service behaviour', async () => {
  const orders = await new OrderRepository().findPaid();
  assert.equal(orders.length, 3);
});

test('OrderRepository.findQuotes returns only non-deleted quote orders', async () => {
  const orders = await new OrderRepository().findQuotes();
  assert.deepEqual(orders.map((o) => o.id), [11]);
  assert.ok(orders.every((o) => o.status === 'quote'));
});
