import assert from 'node:assert/strict';
import { listOrdersForUser, totalPaidCents } from '../src/services/order-service.js';
import { OrderRepository } from '../src/repositories/order-repository.js';

test('listOrdersForUser returns only that user orders', (t, done) => {
  listOrdersForUser(1, (err, orders) => {
    assert.equal(err, null);
    assert.equal(orders.length, 2);
    assert.ok(orders.every((o) => o.user_id === 1));
    done();
  });
});

test('listOrdersForUser reads through OrderRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findByUser = t.mock.method(OrderRepository.prototype, 'findByUser', () => Promise.reject(boom));
  listOrdersForUser(1, (err, orders) => {
    assert.equal(findByUser.mock.callCount(), 1);
    assert.deepEqual(findByUser.mock.calls[0].arguments, [1]);
    assert.equal(err, boom);
    assert.equal(orders, undefined);
    done();
  });
});

test('totalPaidCents counts only paid orders', (t, done) => {
  totalPaidCents((err, total) => {
    assert.equal(err, null);
    assert.equal(total, 4200 + 9900 + 500);
    done();
  });
});

test('totalPaidCents reads through OrderRepository and passes errors to the callback', (t, done) => {
  const boom = new Error('boom');
  const findPaid = t.mock.method(OrderRepository.prototype, 'findPaid', () => Promise.reject(boom));
  totalPaidCents((err, total) => {
    assert.equal(findPaid.mock.callCount(), 1);
    assert.equal(err, boom);
    assert.equal(total, undefined);
    done();
  });
});

